CREATE TABLE [dbo].[ccWhatsAppConversations](	  [conversationId] INT NOT NULL IDENTITY(1,1)	, [inboundId] SMALLINT NOT NULL	, [phoneACD] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [clientId] VARCHAR(25) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [conversationStatus] SMALLINT NOT NULL	, [tChatting] INT NOT NULL	, [tConversation] INT NULL	, [tWrapUp] SMALLINT NOT NULL	, [requestDate] DATETIME NOT NULL DEFAULT(getdate())	, [finishedBy] TINYINT NULL	, [onQueue] BIT NULL	, [tQueue] SMALLINT NOT NULL	, [tTimeout] INT NOT NULL	, [disposition] SMALLINT NOT NULL	, [subDisposition] SMALLINT NOT NULL	, [conversationDate] DATETIME NULL	, [assignDate] DATETIME NULL	, [agentId] INT NULL	, [FirstMessageAgent] DATETIME NULL	, CONSTRAINT [pk_ccWhatsAppMessages_1] PRIMARY KEY ([conversationId] ASC))